dp_app_ui <- function(defaults) {
  s <- defaults
  txt <- function(id, label, ...) shiny::textInput(id, label, s[[id]], ...)
  num <- function(id, label, min = 0, step = 1, ...) shiny::numericInput(id, label, s[[id]], min = min, step = step, ...)
  chk <- function(id, label) shiny::checkboxInput(id, label, s[[id]])
  sel <- function(id, label, choices) shiny::selectInput(id, label, choices, selected = s[[id]])
  area <- function(id, label, rows = 3, placeholder = NULL) shiny::textAreaInput(id, label, s[[id]], rows = rows, placeholder = placeholder, width = "100%")
  note <- function(...) shiny::div(class = "note", ...)
  grid <- function(...) shiny::div(class = "form-grid", ...)
  advanced <- function(title, ...) shiny::tags$details(shiny::tags$summary(title), shiny::div(class = "details-content", ...))
  section <- function(title, text = NULL, ...) shiny::div(class = "section", shiny::h3(title), if (!is.null(text)) shiny::p(class = "muted", text), ...)
  anchor <- function(nm, title, description) shiny::div(class = "anchor-card",
    chk(paste0(nm, "_on"), title), shiny::p(class = "muted", description),
    shiny::conditionalPanel(paste0("input.", nm, "_on"),
      txt(paste0(nm, "_path"), if (nm == "custom") "10 m raster path" else "Polygon layer path"),
      grid(num(paste0(nm, "_buffer"), "Root buffer (m)", step = 10),
        if (nm == "custom") txt("custom_values", "Anchor values (blank = positive values)")),
      advanced("Existing-area accounting",
        note("Root designation alone adds no habitat or hectares. These switches apply to the original source pixels, never to the buffer."),
        chk(paste0(nm, "_existing"), "Also treat source pixels as existing connected habitat"),
        chk(paste0(nm, "_budget"), "Count source pixels toward the whole-polygon nature target"),
        chk(paste0(nm, "_network"), "Count source pixels toward network-area targets"))))
  shiny::fluidPage(
    shiny::tags$head(shiny::tags$title("Denmark restoration · Configuration studio"),
      shiny::tags$link(rel = "stylesheet", type = "text/css", href = "style.css")),
    shiny::div(class = "shell",
      shiny::div(class = "masthead", shiny::div(shiny::div(class = "eyebrow", "DENMARK RESTORATION / V3"),
        shiny::h1("Shape a restoration scenario"), shiny::p("Choose the rules. See their meaning. Export a reproducible configuration.")),
        shiny::div(class = "masthead-badge", "10 m evidence", shiny::tags$br(), "Flexible planning units")),
      shiny::div(class = "workspace",
        shiny::div(class = "editor",
          shiny::tabsetPanel(id = "panel", type = "tabs",
            shiny::tabPanel("1 · Area", value = "area",
              section("Your planning area", "Paths refer to the machine running this app. Relative paths use the project root below.",
                txt("project_root", "Project root"), grid(txt("area_id", "Area ID"), txt("run_id", "Run ID")),
                txt("boundary", "Whole planning polygon"), txt("landuse", "Categorical 10 m land-use raster"), txt("output_root", "Optimization output folder")),
              section("Planning decisions", "The ecological evidence remains at 10 m. Each planning unit receives one restoration decision.",
                grid(num("planning_m", "Planning-unit width (m)", min = 10, step = 10), num("min_unit_ha", "Minimum selectable area per unit (ha)", step = 0.1)),
                grid(chk("agriculture", "Agriculture is selectable"), chk("production_forest", "Production forest is selectable")),
                txt("eligibility_mask", "Optional eligibility mask (positive = selectable)"),
                advanced("Grid and connectivity details", grid(sel("directions", "Neighbours", c("4 · Shared edges" = "4", "8 · Edges and corners" = "8")),
                  num("origin_x", "Grid origin x", min = NA), num("origin_y", "Grid origin y", min = NA)))),
              section("Subareas", "These can have network-size requirements. The nature percentage always applies to the whole polygon.",
                chk("subareas_on", "This area has subareas"), shiny::conditionalPanel("input.subareas_on",
                  txt("subareas", "Subarea polygons"), txt("subarea_id", "ID field (blank = row numbers)"),
                  chk("subarea_goal_on", "Require an anchored network inside each subarea"),
                  shiny::conditionalPanel("input.subarea_goal_on", num("subarea_min", "Network area per subarea (ha)"),
                    area("subarea_goals", "Optional individual goals as JSON", 3, '{"north": 1000, "south": 1500}')))),
              advanced("Existing habitat beyond the planning polygon", txt("context", "Optional wider connectivity boundary"),
                sel("area_scope", "Which existing hectares count for the Global network?", c("Inside planning polygon" = "within_region", "Inside wider context" = "within_context")),
                note("Subarea networks still connect within their own subarea. Include complete relevant patches if their full areas should count."))),
            shiny::tabPanel("2 · Anchors", value = "anchors",
              section("Where can a network be rooted?", "Enable one or several sources. Anchors are eligible roots; designation does not force every anchor to be selected.",
                shiny::div(class = "anchor-card", chk("nature_on", "All current natural areas"), shiny::p(class = "muted", "The eight existing natural habitat classes in the land-use raster.")),
                anchor("political", "Politically designated anchors", "A designation on farmland can become a root when that land is selected for restoration."),
                anchor("lakes", "Lakes and their shores", "The default 10 m buffer allows adjoining land to root a network. Water receives no automatic terrestrial habitat credit."),
                anchor("custom", "My own anchor raster", "Use a raster that is aligned with the 10 m land-use grid."),
                sel("anchor_combine", "Combine enabled sources", c("Union · any enabled source" = "union", "Intersection · overlap of every source" = "intersection")),
                note("Existing natural habitat remains part of the landscape even if it is not enabled as an anchor."),
                advanced("Additional sources", area("extra_anchors", "Named source definitions as JSON", 6,
                  '{"reserve": {"type": "vector", "path": "Datasets/reserve.gpkg", "buffer_m": 0}}'),
                  note("Supports additional nature, vector and raster sources; filters and area-credit flags follow the configuration schema.")))),
            shiny::tabPanel("3 · Biodiversity", value = "biodiversity",
              section("What does a selected cell become?", NULL,
                sel("mode", "Biodiversity model", c("Eight habitat pathways" = "pathways", "One independent restoration outcome" = "single")),
                shiny::conditionalPanel("input.mode == 'single'", note("Supply the output of your separate yes/no model. The app does not combine the eight pathways into this score."),
                  txt("single_score", "Independent score raster")),
                shiny::conditionalPanel("input.mode == 'pathways'", chk("projection_on", "Create new metric layers from saved species models"),
                  shiny::conditionalPanel("!input.projection_on", grid(txt("metrics_dir", "Metric layer folder"), sel("extension", "Raster format", c("VRT" = "vrt", "GeoTIFF" = "tif")))),
                  shiny::conditionalPanel("input.projection_on", note("Configure saved models and tiles in the Projection tab. The score paths will point to that projection's outputs.")),
                  grid(num("richness_weight", "Species richness weight", step = 0.1), num("pd_weight", "Phylogenetic diversity weight", step = 0.1), num("rarity_weight", "Range rarity weight", step = 0.1)),
                  note("These relative weights are normalized to sum to one."), chk("forest_only", "Production-forest units may only take forest pathways"),
                  shiny::conditionalPanel("input.forest_only", num("forest_share", "Production-forest share that activates this rule", step = 0.05, max = 1))),
                sel("score_type", "Score to optimize", c("Expected restored biodiversity" = "endpoint", "Gain relative to current biodiversity" = "gain")),
                shiny::conditionalPanel("input.score_type == 'gain' && input.mode == 'single'", txt("single_baseline", "Independent model's current baseline raster")),
                shiny::conditionalPanel("input.score_type == 'gain' && input.mode == 'pathways' && !input.projection_on", txt("baseline_dir", "Folder with current metric layers")),
                advanced("Individual paths, feasibility masks and scales", area("outcome_overrides", "Outcome overrides as JSON", 6,
                  '{"forest_dry_poor": {"allowed_mask": "Datasets/forest_suitability.tif"}}'),
                  note("Allowed masks are hard feasibility rules: every eligible pixel in a planning unit must pass. Scores may also be overridden by metric name."),
                  area("metric_scales", "Optional fixed metric scales as JSON", 3, '{"Richness": 400, "PD": 3000, "RangeRarity": 5}'))),
              section("Expected score files", "These are the exact paths that will go into the configuration.", shiny::tableOutput("score_files"))),
            shiny::tabPanel("4 · Targets", value = "targets",
              section("Whole-polygon nature target", "Current credited nature plus new restoration must reach the target.",
                chk("target_on", "Set a percentage target for the whole polygon"), shiny::conditionalPanel("input.target_on",
                  num("target_percent", "Nature target (%)", step = 1, max = 100), chk("tolerance_on", "Limit restoration above the area needed for this target"),
                  shiny::conditionalPanel("input.tolerance_on", num("tolerance_ha", "Allowed extra restoration (ha)")))),
              section("Restoration and cost budget", "These limits apply together with the percentage and network requirements.",
                num("min_ha", "Minimum new restoration (ha)"), chk("max_on", "Also set an absolute maximum"),
                shiny::conditionalPanel("input.max_on", num("max_ha", "Maximum new restoration (ha)")),
                chk("cost_on", "Apply a monetary budget"), shiny::conditionalPanel("input.cost_on",
                  num("cost_cap", "Maximum cost", step = 100000), txt("cost_raster", "Restoration cost per hectare raster"))),
              section("Connected nature networks", NULL, chk("global_on", "Require a Global anchored network"),
                shiny::conditionalPanel("input.global_on", num("global_min", "Global network minimum (ha)")),
                chk("require_new", "Each required network must include new restoration"),
                note("Network area may include credited existing habitat. Subarea network requirements are set in the Area tab."))),
            shiny::tabPanel("5 · Workflow", value = "workflow",
              section("From a starting pattern to a feasible solution", NULL, shiny::uiOutput("workflow_cards")),
              section("Spatial preferences", "These are soft objective weights. Network and budget requirements remain hard constraints in repair and final optimization.",
                grid(num("warmup_weight", "Warm-up spatial weight", step = 0.1), num("quality_weight", "Final spatial weight", step = 0.1)),
                grid(num("new_weight", "New-to-new adjacency weight", step = 0.1), num("anchor_weight", "Anchor-contact weight", step = 0.1)),
                note("A final spatial weight of zero gives a biodiversity-only final objective. New-to-new adjacency rewards the same pathway on neighbouring units.")),
              section("Repair and final location choices", NULL,
                chk("repair_on", "Attempt a separate repair when shortfall remains"),
                shiny::conditionalPanel("input.repair_on", num("repair_minutes", "Minutes per repair attempt", min = 1/60),
                  note("Repair enforces zero shortfall and minimizes changed hectares from the partial solution. It can add and remove units while respecting all budgets. A time-limited attempt may find no feasible repair.")),
                sel("footprint", "During final optimization", c("Allow locations and pathways to improve" = "free", "Limit changed hectares" = "capped", "Keep locations fixed; improve pathways" = "fixed")),
                shiny::conditionalPanel("input.footprint == 'capped'", num("change_cap", "Maximum changed hectares", step = 1)),
                note("The reference is the first feasible solution entering the final phase. Change means additions + removals; exchanging 100 ha for another 100 ha counts as 200 ha."),
                shiny::conditionalPanel("input.footprint == 'fixed' && input.mode == 'single'", note("With a fixed footprint and a single outcome, the biodiversity decision is already determined."))),
              section("Solver time and continuation", "Times are limits, not runtime estimates. Each comma-separated entry creates a resumable stage.",
                grid(num("warmup_minutes", "Warm-up (minutes)", min = 1/60), txt("feasibility_minutes", "Shortfall stages (minutes)"), txt("quality_minutes", "Final stages (minutes)")),
                grid(sel("solver", "AMPL solver", c("Gurobi" = "gurobi", "HiGHS" = "highs")), num("gap_percent", "Repair/final relative gap (%)", step = 0.1, max = 99.9)),
                advanced("Solver paths and options", txt("ampl", "AMPL executable"), txt("solver_options", "Additional solver options")))),
            shiny::tabPanel("6 · Projection", value = "projection",
              shiny::conditionalPanel("input.mode != 'pathways' || !input.projection_on", note("Projection settings are inactive for this configuration. Enable new metric projections in the Biodiversity tab to use them.")),
              section("Reuse saved species models", "These settings create current + eight all-selectable-cells-to-one-pathway scenarios. No models are refitted.",
                grid(txt("projection_id", "Projection ID"), txt("projection_output", "Projection output folder")),
                txt("saved_fit_root", "Saved fit root"), txt("training_manifest", "Training predictor manifest"),
                txt("climate_manifest", "Original climate-source manifest"), txt("climate", "Optional direct climate raster (overrides manifest)"),
                txt("projection_boundary", "Optional separate projection boundary (blank = planning area)")),
              section("Tiles and workers", "Worker memory is a terra memory hint per process, not a hard total-RAM limit.",
                grid(num("tile_cells", "Tile width (10 m cells)", min = 1), num("workers", "Parallel tile workers", min = 1), num("mem_gb", "Memory hint per worker (GB)", min = 0.1, step = 0.5)),
                shiny::textOutput("tile_summary"), chk("keep_species", "Keep intermediate species prediction rasters"),
                advanced("Metric processing", grid(num("blocks", "Blocks in memory", min = 1), num("chunk", "Metric chunk size", min = 1), num("pd_cells", "PD cell limit", min = 1))))),
            shiny::tabPanel("7 · Review & export", value = "review",
              section("Check the configuration", "File checks and anchor previews do not run the optimizer or species projections.",
                shiny::actionButton("check_files", "Check input files", class = "btn-secondary"),
                shiny::uiOutput("file_status"), advanced("Show input-file details", shiny::tableOutput("file_check"))),
              section("Preview current nature and anchors", "Build exact 10 m masks in a temporary preview folder. Large maps are sampled for display only.",
                shiny::actionButton("preview", "Build map preview", class = "btn-primary"),
                shiny::textOutput("preview_status"), shiny::uiOutput("preview_controls"),
                shiny::plotOutput("map", height = "440px"), shiny::tableOutput("preview_ledger"),
                note("Preview hectares precede the minimum-unit and outcome-feasibility filters. Full preparation and the final independent audit determine feasibility.")),
              section("Export and run", "The R configuration is ready for the pipeline. The settings JSON lets you reopen this form later.",
                shiny::uiOutput("export_controls"), shiny::downloadButton("settings_download", "Save editable settings"),
                shiny::h4("Run from your project root"), shiny::verbatimTextOutput("commands"),
                advanced("Generated R configuration", shiny::verbatimTextOutput("config_code")))))),
        shiny::div(class = "sidebar",
          shiny::div(class = "sidebar-card", shiny::div(class = "eyebrow", "YOUR SCENARIO"), shiny::uiOutput("status"), shiny::uiOutput("summary")),
          shiny::div(class = "sidebar-card", shiny::h4("Explore the options"), shiny::p("Try the small synthetic landscape to explore anchors, subareas and model choices."),
            shiny::actionButton("demo", "Load a synthetic example", class = "btn-default"), shiny::textOutput("demo_status"),
            shiny::tags$hr(), shiny::fileInput("settings_upload", "Reopen app settings", accept = ".json"),
            shiny::p(class = "muted small", "Load JSON exported by this app. Existing hand-written R configs can still be run directly through the pipeline."))))),
    shiny::div(class = "footer", "Configuration studio · Denmark restoration pipeline · Budgets and network targets are checked again by the solver and the independent 10 m audit.")
  )
}
